 220	/// State required for all charset operations.
 221	pub const CharsetState = struct {
 222	    /// The list of graphical charsets by slot
 223	    charsets: CharsetArray = .{},
 224	
 225	    /// GL is the slot to use when using a 7-bit printable char (up to 127)
 226	    /// GR used for 8-bit printable chars.
 227	    gl: charsets.Slots = .G0,
 228	    gr: charsets.Slots = .G2,
 229	
 230	    /// Single shift where a slot is used for exactly one char.
 231	    single_shift: ?charsets.Slots = null,
 232	
 233	    /// An array to map a charset slot to a lookup table.
 234	    ///
 235	    /// We use this bespoke struct instead of `std.EnumArray` because
 236	    /// accessing these slots is very performance critical since it's
 237	    /// done for every single print. This benchmarks faster.
 238	    const CharsetArray = struct {
 239	        g0: charsets.Charset = .utf8,
 240	        g1: charsets.Charset = .utf8,
 241	        g2: charsets.Charset = .utf8,
 242	        g3: charsets.Charset = .utf8,
 243	
 244	        pub inline fn get(
 245	            self: *const CharsetArray,
 246	            slot: charsets.Slots,
 247	        ) charsets.Charset {
 248	            return switch (slot) {
 249	                .G0 => self.g0,
 250	                .G1 => self.g1,
 251	                .G2 => self.g2,
 252	                .G3 => self.g3,
 253	            };
 254	        }
 255	
 256	        pub inline fn set(
 257	            self: *CharsetArray,
 258	            slot: charsets.Slots,
 259	            charset: charsets.Charset,
 260	        ) void {
 261	            switch (slot) {
 262	                .G0 => self.g0 = charset,
 263	                .G1 => self.g1 = charset,
 264	                .G2 => self.g2 = charset,
 265	                .G3 => self.g3 = charset,
 266	            }
 267	        }
 268	    };
 269	};
