 286	    /// screen. Kitty image storage is per-screen.
 287	    kitty_image_storage_limit: usize = switch (build_options.artifact) {
 288	        .ghostty => 320 * 1000 * 1000, // 320MB
 289	        .lib => 10 * 1000 * 1000, // 10MB
 290	    },
