 292	    /// The limits for what medium types are allowed for Kitty image loading.
 293	    kitty_image_loading_limits: if (build_options.kitty_graphics)
 294	        kitty.graphics.LoadingImage.Limits
 295	    else
 296	        void = if (build_options.kitty_graphics) .direct else {},
